"""Robustness: run steal.py against several synthetic networks with
different seed / neuron count / scale, check direction recovery."""
import os, shutil, subprocess, sys, importlib.util
import numpy as np

def load_forward(path):
    spec = importlib.util.spec_from_file_location("fwd_" + os.path.basename(path), path)
    m = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(m)
    return m

def make_forward(path, seed, n, scale, dim=10):
    src = f'''import numpy as np
np.random.seed({seed})
A1 = np.random.randn({n}, {dim}) * {scale}
b1 = np.random.randn({n}) * {scale}
A2 = np.random.randn(1, {n}) * {scale}
b2 = np.random.randn(1) * {scale}
def relu(x): return np.maximum(0, x)
def forward(x):
    x = np.array(x).reshape(-1)
    assert x.shape[0] == {dim}
    return float((A2 @ relu(A1 @ x + b1)) + b2)
'''
    open(path, "w").write(src)

def recover(path, seed, n, scale):
    work = f"/tmp/rob_{seed}_{n}"
    os.makedirs(work, exist_ok=True)
    make_forward(f"{work}/forward.py", seed, n, scale)
    shutil.copy("/app/steal.py", f"{work}/steal.py")
    r = subprocess.run([sys.executable, f"{work}/steal.py"],
                       capture_output=True, text=True, cwd=work, timeout=300)
    if r.returncode != 0:
        return None, "CRASH\n" + (r.stderr or r.output)[-800:]
    m = load_forward(f"{work}/forward.py")
    S = np.load(f"/app/stolen_A1.npy")
    if S.shape != (n, 10):
        return None, f"shape {S.shape} != {(n,10)} (recovered {S.shape[0]})"
    Sn = S / np.linalg.norm(S, axis=1, keepdims=True)
    An = m.A1 / np.linalg.norm(m.A1, axis=1, keepdims=True)
    cos = np.abs(Sn @ An.T)
    matched = {}
    for k in np.argsort(-cos, axis=None):
        i, j = divmod(int(k), cos.shape[1])
        if i not in matched and j not in matched.values():
            matched[i] = j
    if len(matched) < n:
        return None, f"only {len(matched)}/{n} bijective matches"
    sims = [cos[i, matched[i]] for i in matched]
    return (min(sims), max(sims)), None

configs = [
    (1234, 20, 0.1),   # same size, different seed
    (7, 15, 0.3),      # fewer neurons, bigger scale
    (99, 30, 0.1),     # more neurons
    (5, 25, 0.05),     # smaller scale
    (2024, 12, 0.2),   # small net
]
for seed, n, scale in configs:
    res, err = recover(f"cfg{seed}_{n}", seed, n, scale)
    if err:
        print(f"seed={seed:5d} n={n:3d} scale={scale}: FAIL {err}")
    else:
        print(f"seed={seed:5d} n={n:3d} scale={scale}: PASS min|cos|={res[0]:.12f} max|cos|={res[1]:.12f}")
